-- Original frf eligibility and original ProtoItem field58 appearance authority.
CREATE TABLE native_item_fusion_targets(reference integer PRIMARY KEY CHECK(reference>0),item_level integer NOT NULL CHECK(item_level>=0),normalized_type integer NOT NULL CHECK(normalized_type>0),source_sha256 text NOT NULL CHECK(source_sha256 ~ '^[0-9a-f]{64}$'));
CREATE TABLE inventory_item_appearances(uid bigint PRIMARY KEY REFERENCES inventory_items(uid) ON DELETE CASCADE,appearance_ref integer NOT NULL REFERENCES native_item_fusion_targets(reference));
CREATE TABLE item_fusion_receipts(account_id bigint NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,character_id bigint NOT NULL REFERENCES characters(id) ON DELETE CASCADE,mimibionte_uid bigint NOT NULL,stat_uid bigint NOT NULL,skin_uid bigint NOT NULL,stat_ref integer NOT NULL,skin_ref integer NOT NULL,appearance_ref integer NOT NULL,PRIMARY KEY(account_id,mimibionte_uid,stat_uid,skin_uid));
